import java.util.*; class PerformanceTest{ public static void main(String[] args){ int n=100000; int[] a=new int[n]; long t1=System.currentTimeMillis(); for(int i=0;i<n;i++) a[i]=i; int s1=0; for(int i=0;i<n;i++) s1+=a[i]; long t2=System.currentTimeMillis(); ArrayList<Integer> l=new ArrayList<>(); long t3=System.currentTimeMillis(); for(int i=0;i<n;i++) l.add(i); int s2=0; for(int i:l) s2+=i; long t4=System.currentTimeMillis(); System.out.println(t2-t1); System.out.println(t4-t3);} }